const fs = require('fs'), path = require('path')
const files = {}

files["app/admin/settings/VerticalSettings.tsx"] = "// app/admin/settings/VerticalSettings.tsx\n'use client'\nimport { useState } from 'react'\nimport { useRouter } from 'next/navigation'\nimport { createClient } from '@/lib/supabase/client'\nimport { getVertical, type VerticalType } from '@/lib/verticals'\nimport { Clock, Truck, Store, Timer, Check, Loader2, Building2, Phone, MapPin, ChefHat, Scissors } from 'lucide-react'\nimport { cn } from '@/lib/utils'\n\nconst DAYS_SHORT = ['Dom','Lun','Mar','Mié','Jue','Vie','Sáb']\nconst DAYS_FULL  = ['Domingo','Lunes','Martes','Miércoles','Jueves','Viernes','Sábado']\n\ninterface Props {\n  businessId: string\n  verticalType: VerticalType\n  business: Record<string, unknown>\n  hours: { day_of_week: number; is_open: boolean; open_time: string; close_time: string }[]\n  branches: { id: string; name: string; address?: string; phone?: string; is_main: boolean }[]\n  staff: { id: string; name: string; role: string }[]\n}\n\nexport default function VerticalSettings({ businessId, verticalType, business, hours: initHours, branches: initBranches, staff: initStaff }: Props) {\n  const vertical = getVertical(verticalType)\n  const router   = useRouter()\n\n  return (\n    <div className=\"space-y-3\">\n      <div className=\"rounded-2xl overflow-hidden border border-gray-100 shadow-sm\">\n        {/* Header vertical */}\n        <div className=\"flex items-center gap-3 px-5 py-4 border-b border-gray-100\"\n          style={{ background: vertical.accentColor }}>\n          <span className=\"text-2xl\">{vertical.emoji}</span>\n          <div>\n            <p className=\"text-sm font-bold text-gray-900\">Configuración de {vertical.label}</p>\n            <p className=\"text-xs text-gray-500\">Ajustes específicos para tu tipo de negocio</p>\n          </div>\n        </div>\n\n        <div className=\"divide-y divide-gray-50 bg-white\">\n          {/* FOOD */}\n          {verticalType === 'food' && (\n            <FoodConfig businessId={businessId} business={business} hours={initHours} />\n          )}\n\n          {/* BARBERSHOP / BEAUTY */}\n          {(verticalType === 'barbershop' || verticalType === 'beauty') && (\n            <BarberConfig businessId={businessId} business={business} hours={initHours}\n              branches={initBranches} staff={initStaff} verticalType={verticalType} />\n          )}\n\n          {/* FASHION */}\n          {verticalType === 'fashion' && (\n            <FashionConfig businessId={businessId} business={business} />\n          )}\n\n          {/* SERVICES / REAL_ESTATE / GENERAL */}\n          {(verticalType === 'services' || verticalType === 'real_estate' || verticalType === 'general') && (\n            <GeneralConfig businessId={businessId} business={business} />\n          )}\n        </div>\n      </div>\n    </div>\n  )\n}\n\n/* ── Collapsible section ── */\nfunction Section({ title, icon: Icon, children, open: initOpen = false }: {\n  title: string; icon: React.ElementType; children: React.ReactNode; open?: boolean\n}) {\n  const [open, setOpen] = useState(initOpen)\n  return (\n    <div>\n      <button onClick={() => setOpen(o => !o)}\n        className=\"w-full flex items-center justify-between px-5 py-3.5\n                   hover:bg-gray-50 transition-colors text-left\">\n        <div className=\"flex items-center gap-2.5\">\n          <Icon size={15} className=\"text-gray-400\" />\n          <p className=\"text-sm font-semibold text-gray-800\">{title}</p>\n        </div>\n        <span className={cn('text-xs text-gray-400 transition-transform', open && 'rotate-180')}>▼</span>\n      </button>\n      {open && <div className=\"px-5 pb-5 space-y-4\">{children}</div>}\n    </div>\n  )\n}\n\n/* ── Save button ── */\nfunction SaveBtn({ onClick, saving, saved }: { onClick: () => void; saving: boolean; saved: boolean }) {\n  return (\n    <button onClick={onClick} disabled={saving}\n      className=\"flex items-center gap-2 rounded-xl px-4 py-2 text-xs font-semibold text-white disabled:opacity-40\"\n      style={{ background: saved ? '#10B981' : '#1565FF' }}>\n      {saving ? <Loader2 size={12} className=\"animate-spin\" /> : <Check size={12} />}\n      {saving ? 'Guardando...' : saved ? 'Guardado ✓' : 'Guardar'}\n    </button>\n  )\n}\n\n/* ── Toggle ── */\nfunction Toggle({ value, onChange, label }: { value: boolean; onChange: (v: boolean) => void; label: string }) {\n  return (\n    <label className=\"flex items-center gap-3 cursor-pointer select-none\">\n      <button type=\"button\" onClick={() => onChange(!value)}\n        className={cn('relative h-5 w-9 rounded-full transition-colors', value ? 'bg-blue-500' : 'bg-gray-200')}>\n        <span className={cn('absolute top-0.5 h-4 w-4 rounded-full bg-white shadow transition-transform',\n          value ? 'left-4' : 'left-0.5')} />\n      </button>\n      <span className=\"text-sm text-gray-700\">{label}</span>\n    </label>\n  )\n}\n\n// ════════════ FOOD CONFIG ════════════\nfunction FoodConfig({ businessId, business, hours: initHours }: {\n  businessId: string; business: Record<string, unknown>\n  hours: { day_of_week: number; is_open: boolean; open_time: string; close_time: string }[]\n}) {\n  const supabase = createClient()\n  const [saving,  setSaving]  = useState(false)\n  const [saved,   setSaved]   = useState(false)\n\n  const [deliveryEnabled, setDeliveryEnabled] = useState((business.delivery_enabled as boolean) ?? true)\n  const [pickupEnabled,   setPickupEnabled]   = useState((business.pickup_enabled as boolean) ?? true)\n  const [deliveryFee,     setDeliveryFee]     = useState(String(business.delivery_fee ?? '0'))\n  const [minOrder,        setMinOrder]        = useState(String(business.min_order ?? '0'))\n  const [estimatedTime,   setEstimatedTime]   = useState((business.estimated_time as string) ?? '30-45 min')\n\n  const [hours, setHours] = useState(\n    DAYS_SHORT.map((_, i) => initHours.find(h => h.day_of_week === i) ?? {\n      day_of_week: i, is_open: i > 0 && i < 6, open_time: '11:00', close_time: '23:00'\n    })\n  )\n  const [savingDay, setSavingDay] = useState<number | null>(null)\n\n  async function saveDelivery() {\n    setSaving(true)\n    await fetch('/api/business/settings', {\n      method: 'PATCH',\n      headers: { 'Content-Type': 'application/json' },\n      body: JSON.stringify({\n        delivery_enabled: deliveryEnabled,\n        pickup_enabled:   pickupEnabled,\n        delivery_fee:     parseFloat(deliveryFee) || 0,\n        min_order:        parseFloat(minOrder) || 0,\n        estimated_time:   estimatedTime,\n      }),\n    })\n    setSaved(true); setTimeout(() => setSaved(false), 2000); setSaving(false)\n  }\n\n  async function saveDay(h: typeof hours[0]) {\n    setSavingDay(h.day_of_week)\n    await supabase.from('business_hours').upsert({\n      business_id: businessId, day_of_week: h.day_of_week,\n      is_open: h.is_open, open_time: h.open_time, close_time: h.close_time,\n    }, { onConflict: 'business_id,day_of_week' })\n    setSavingDay(null)\n  }\n\n  function updateHour(day: number, field: string, value: unknown) {\n    setHours(prev => prev.map(h => h.day_of_week === day ? { ...h, [field]: value } : h))\n  }\n\n  return (\n    <>\n      <Section title=\"Delivery & Retiro\" icon={Truck} open>\n        <div className=\"space-y-3\">\n          <Toggle value={deliveryEnabled} onChange={setDeliveryEnabled} label=\"Delivery activado\" />\n          <Toggle value={pickupEnabled}   onChange={setPickupEnabled}   label=\"Retiro en local\" />\n\n          <div className=\"grid grid-cols-2 gap-3 pt-1\">\n            <div>\n              <label className=\"field-label text-xs\">Costo de delivery</label>\n              <input type=\"number\" min=\"0\" step=\"10\" value={deliveryFee}\n                onChange={e => setDeliveryFee(e.target.value)}\n                placeholder=\"0 = gratis\" className=\"input-base text-sm py-2\" />\n            </div>\n            <div>\n              <label className=\"field-label text-xs\">Pedido mínimo</label>\n              <input type=\"number\" min=\"0\" step=\"10\" value={minOrder}\n                onChange={e => setMinOrder(e.target.value)}\n                placeholder=\"0 = sin mínimo\" className=\"input-base text-sm py-2\" />\n            </div>\n          </div>\n\n          <div>\n            <label className=\"field-label text-xs\">Tiempo estimado de entrega</label>\n            <div className=\"flex items-center gap-2 flex-wrap\">\n              {['15-25 min','20-35 min','30-45 min','45-60 min','1 hora'].map(t => (\n                <button key={t} type=\"button\" onClick={() => setEstimatedTime(t)}\n                  className={cn('rounded-xl px-3 py-1.5 text-xs font-medium transition-all',\n                    estimatedTime === t\n                      ? 'bg-blue-500 text-white'\n                      : 'bg-gray-100 text-gray-600 hover:bg-gray-200')}>\n                  {t}\n                </button>\n              ))}\n              <input type=\"text\" value={estimatedTime}\n                onChange={e => setEstimatedTime(e.target.value)}\n                className=\"rounded-xl border border-gray-200 px-3 py-1.5 text-xs w-28\" />\n            </div>\n          </div>\n\n          <SaveBtn onClick={saveDelivery} saving={saving} saved={saved} />\n        </div>\n      </Section>\n\n      <Section title=\"Horarios de atención\" icon={Clock}>\n        <div className=\"space-y-2\">\n          {hours.map(h => (\n            <div key={h.day_of_week} className=\"flex items-center gap-3\">\n              <button onClick={() => updateHour(h.day_of_week, 'is_open', !h.is_open)}\n                className={cn('relative h-5 w-9 rounded-full transition-colors shrink-0',\n                  h.is_open ? 'bg-green-500' : 'bg-gray-200')}>\n                <span className={cn('absolute top-0.5 h-4 w-4 rounded-full bg-white shadow transition-transform',\n                  h.is_open ? 'left-4' : 'left-0.5')} />\n              </button>\n              <p className={cn('text-sm font-semibold w-8 shrink-0',\n                h.is_open ? 'text-gray-900' : 'text-gray-400')}>\n                {DAYS_SHORT[h.day_of_week]}\n              </p>\n              {h.is_open ? (\n                <div className=\"flex items-center gap-2 flex-1\">\n                  <input type=\"time\" value={h.open_time}\n                    onChange={e => updateHour(h.day_of_week, 'open_time', e.target.value)}\n                    className=\"rounded-xl border border-gray-200 px-2 py-1.5 text-xs flex-1\" />\n                  <span className=\"text-xs text-gray-400 shrink-0\">a</span>\n                  <input type=\"time\" value={h.close_time}\n                    onChange={e => updateHour(h.day_of_week, 'close_time', e.target.value)}\n                    className=\"rounded-xl border border-gray-200 px-2 py-1.5 text-xs flex-1\" />\n                </div>\n              ) : (\n                <p className=\"text-xs text-gray-400 flex-1\">Cerrado</p>\n              )}\n              <button onClick={() => saveDay(h)}\n                disabled={savingDay === h.day_of_week}\n                className=\"flex h-7 w-7 items-center justify-center rounded-lg text-white shrink-0\"\n                style={{ background: '#1565FF' }}>\n                {savingDay === h.day_of_week\n                  ? <Loader2 size={11} className=\"animate-spin\" />\n                  : <Check size={11} />}\n              </button>\n            </div>\n          ))}\n        </div>\n      </Section>\n    </>\n  )\n}\n\n// ════════════ BARBER CONFIG ════════════\nfunction BarberConfig({ businessId, business, hours: initHours, branches: initBranches, staff: initStaff, verticalType }: {\n  businessId: string; business: Record<string, unknown>\n  hours: { day_of_week: number; is_open: boolean; open_time: string; close_time: string }[]\n  branches: { id: string; name: string; address?: string; phone?: string; is_main: boolean }[]\n  staff: { id: string; name: string; role: string }[]\n  verticalType: string\n}) {\n  const supabase = createClient()\n  const [hours,    setHours]    = useState(DAYS_SHORT.map((_, i) =>\n    initHours.find(h => h.day_of_week === i) ?? { day_of_week: i, is_open: i>0&&i<6, open_time:'09:00', close_time:'19:00' }\n  ))\n  const [branches, setBranches] = useState(initBranches)\n  const [staff,    setStaff]    = useState(initStaff)\n  const [savingDay, setSavingDay] = useState<number|null>(null)\n  const [saving,    setSaving]   = useState(false)\n\n  // Nuevo barbero\n  const [newStaffName, setNewStaffName] = useState('')\n  const [newBranchName, setNewBranchName] = useState('')\n  const [newBranchAddr, setNewBranchAddr] = useState('')\n\n  async function saveDay(h: typeof hours[0]) {\n    setSavingDay(h.day_of_week)\n    await supabase.from('business_hours').upsert({\n      business_id: businessId, day_of_week: h.day_of_week,\n      is_open: h.is_open, open_time: h.open_time, close_time: h.close_time,\n    }, { onConflict: 'business_id,day_of_week' })\n    setSavingDay(null)\n  }\n\n  function updateHour(day: number, field: string, value: unknown) {\n    setHours(prev => prev.map(h => h.day_of_week === day ? { ...h, [field]: value } : h))\n  }\n\n  async function addStaff() {\n    if (!newStaffName.trim()) return\n    setSaving(true)\n    const { data } = await supabase.from('staff').insert({\n      business_id: businessId, name: newStaffName.trim(),\n      role: verticalType === 'barbershop' ? 'barber' : 'specialist',\n      color: '#1565FF', active: true,\n    }).select('id,name,role').single()\n    if (data) { setStaff(prev => [...prev, data]); setNewStaffName('') }\n    setSaving(false)\n  }\n\n  async function addBranch() {\n    if (!newBranchName.trim()) return\n    setSaving(true)\n    const { data } = await supabase.from('branches').insert({\n      business_id: businessId, name: newBranchName.trim(),\n      address: newBranchAddr.trim() || null, is_main: false, active: true,\n    }).select('id,name,address,phone,is_main').single()\n    if (data) { setBranches(prev => [...prev, data]); setNewBranchName(''); setNewBranchAddr('') }\n    setSaving(false)\n  }\n\n  const isBarber = verticalType === 'barbershop'\n\n  return (\n    <>\n      <Section title=\"Horarios de atención\" icon={Clock} open>\n        <div className=\"space-y-2\">\n          {hours.map(h => (\n            <div key={h.day_of_week} className=\"flex items-center gap-2.5\">\n              <button onClick={() => updateHour(h.day_of_week, 'is_open', !h.is_open)}\n                className={cn('relative h-5 w-9 rounded-full transition-colors shrink-0',\n                  h.is_open ? 'bg-green-500' : 'bg-gray-200')}>\n                <span className={cn('absolute top-0.5 h-4 w-4 rounded-full bg-white shadow transition-transform',\n                  h.is_open ? 'left-4' : 'left-0.5')} />\n              </button>\n              <p className={cn('text-sm font-semibold w-8 shrink-0', h.is_open ? 'text-gray-900' : 'text-gray-400')}>\n                {DAYS_SHORT[h.day_of_week]}\n              </p>\n              {h.is_open ? (\n                <div className=\"flex items-center gap-2 flex-1\">\n                  <input type=\"time\" value={h.open_time}\n                    onChange={e => updateHour(h.day_of_week,'open_time',e.target.value)}\n                    className=\"rounded-xl border border-gray-200 px-2 py-1.5 text-xs flex-1\"/>\n                  <span className=\"text-xs text-gray-400 shrink-0\">a</span>\n                  <input type=\"time\" value={h.close_time}\n                    onChange={e => updateHour(h.day_of_week,'close_time',e.target.value)}\n                    className=\"rounded-xl border border-gray-200 px-2 py-1.5 text-xs flex-1\"/>\n                </div>\n              ) : (\n                <p className=\"text-xs text-gray-400 flex-1\">Cerrado</p>\n              )}\n              <button onClick={() => saveDay(h)} disabled={savingDay===h.day_of_week}\n                className=\"flex h-7 w-7 items-center justify-center rounded-lg text-white shrink-0\"\n                style={{background:'#1565FF'}}>\n                {savingDay===h.day_of_week ? <Loader2 size={11} className=\"animate-spin\"/> : <Check size={11}/>}\n              </button>\n            </div>\n          ))}\n        </div>\n      </Section>\n\n      <Section title={isBarber ? 'Barberos' : 'Profesionales'} icon={Scissors}>\n        <div className=\"space-y-2\">\n          {staff.length === 0 && (\n            <p className=\"text-xs text-gray-400\">Sin {isBarber?'barberos':'profesionales'} registrados</p>\n          )}\n          {staff.map(s => (\n            <div key={s.id} className=\"flex items-center gap-3 bg-gray-50 rounded-xl px-3 py-2.5\">\n              <div className=\"h-8 w-8 rounded-xl bg-blue-500 flex items-center justify-center\n                              text-white text-xs font-bold shrink-0\">\n                {s.name.slice(0,1).toUpperCase()}\n              </div>\n              <div>\n                <p className=\"text-sm font-semibold text-gray-900\">{s.name}</p>\n                <p className=\"text-xs text-gray-400 capitalize\">{s.role}</p>\n              </div>\n            </div>\n          ))}\n          {/* Agregar nuevo */}\n          <div className=\"flex items-center gap-2 pt-2\">\n            <input type=\"text\" value={newStaffName} onChange={e => setNewStaffName(e.target.value)}\n              placeholder={`Nombre del ${isBarber?'barbero':'profesional'}`}\n              className=\"input-base flex-1 py-2 text-sm\"\n              onKeyDown={e => e.key==='Enter' && addStaff()} />\n            <button onClick={addStaff} disabled={saving || !newStaffName.trim()}\n              className=\"flex h-9 w-9 items-center justify-center rounded-xl text-white disabled:opacity-40\"\n              style={{background:'#1565FF'}}>\n              {saving ? <Loader2 size={13} className=\"animate-spin\"/> : <span className=\"text-lg leading-none\">+</span>}\n            </button>\n          </div>\n          <p className=\"text-xs text-blue-600\">\n            → Para gestión completa de agenda ir a <a href=\"/admin/barbershop\" className=\"underline\">Agenda</a>\n          </p>\n        </div>\n      </Section>\n\n      <Section title=\"Sucursales\" icon={Building2}>\n        <div className=\"space-y-2\">\n          {branches.map(b => (\n            <div key={b.id} className=\"bg-gray-50 rounded-xl px-3 py-2.5\">\n              <div className=\"flex items-center gap-2\">\n                <Building2 size={13} className=\"text-gray-400 shrink-0\"/>\n                <p className=\"text-sm font-semibold text-gray-900\">{b.name}</p>\n                {b.is_main && <span className=\"text-[10px] text-blue-600 font-bold\">Principal</span>}\n              </div>\n              {b.address && (\n                <p className=\"text-xs text-gray-500 mt-0.5 pl-5 flex items-center gap-1\">\n                  <MapPin size={10}/> {b.address}\n                </p>\n              )}\n            </div>\n          ))}\n          {/* Nueva sucursal */}\n          <div className=\"space-y-2 pt-2\">\n            <input type=\"text\" value={newBranchName} onChange={e => setNewBranchName(e.target.value)}\n              placeholder=\"Nombre de la sucursal\" className=\"input-base py-2 text-sm\"/>\n            <input type=\"text\" value={newBranchAddr} onChange={e => setNewBranchAddr(e.target.value)}\n              placeholder=\"Dirección (opcional)\" className=\"input-base py-2 text-sm\"/>\n            <button onClick={addBranch} disabled={saving || !newBranchName.trim()}\n              className=\"flex items-center gap-2 rounded-xl px-4 py-2 text-xs font-semibold text-white disabled:opacity-40\"\n              style={{background:'#1565FF'}}>\n              {saving ? <Loader2 size={12} className=\"animate-spin\"/> : null}\n              + Agregar sucursal\n            </button>\n          </div>\n          <p className=\"text-xs text-blue-600\">\n            → Para gestión completa ir a <a href=\"/admin/barbershop\" className=\"underline\">Agenda → Sucursales</a>\n          </p>\n        </div>\n      </Section>\n\n      <Section title=\"Duración de turnos\" icon={Clock}>\n        <div>\n          <label className=\"field-label text-xs\">Duración por defecto de cada turno</label>\n          <div className=\"flex flex-wrap gap-2\">\n            {[15,20,30,45,60,90].map(m => (\n              <button key={m} type=\"button\"\n                className=\"rounded-xl px-3 py-1.5 text-xs font-medium bg-gray-100 text-gray-700 hover:bg-blue-50 hover:text-blue-700\">\n                {m} min\n              </button>\n            ))}\n          </div>\n          <p className=\"text-xs text-gray-400 mt-2\">\n            Podés ajustar la duración por servicio en <a href=\"/admin/products\" className=\"text-blue-600 underline\">Servicios</a>\n          </p>\n        </div>\n      </Section>\n    </>\n  )\n}\n\n// ════════════ FASHION CONFIG ════════════\nfunction FashionConfig({ businessId, business }: { businessId: string; business: Record<string, unknown> }) {\n  const [saving, setSaving] = useState(false)\n  const [saved,  setSaved]  = useState(false)\n  const [allowPickup,   setAllowPickup]   = useState((business.pickup_enabled as boolean) ?? true)\n  const [allowDelivery, setAllowDelivery] = useState((business.delivery_enabled as boolean) ?? true)\n\n  async function save() {\n    setSaving(true)\n    await fetch('/api/business/settings', {\n      method: 'PATCH', headers: { 'Content-Type': 'application/json' },\n      body: JSON.stringify({ pickup_enabled: allowPickup, delivery_enabled: allowDelivery }),\n    })\n    setSaved(true); setTimeout(() => setSaved(false), 2000); setSaving(false)\n  }\n\n  return (\n    <Section title=\"Envíos y retiro\" icon={Truck} open>\n      <div className=\"space-y-3\">\n        <Toggle value={allowDelivery} onChange={setAllowDelivery} label=\"Envíos a domicilio\" />\n        <Toggle value={allowPickup}   onChange={setAllowPickup}   label=\"Retiro en local / showroom\" />\n        <div className=\"rounded-xl bg-blue-50 px-4 py-3 text-xs text-blue-700\">\n          💡 Gestioná talles y variantes en cada producto desde{' '}\n          <a href=\"/admin/products\" className=\"underline font-semibold\">Productos</a>\n        </div>\n        <SaveBtn onClick={save} saving={saving} saved={saved} />\n      </div>\n    </Section>\n  )\n}\n\n// ════════════ GENERAL / SERVICES / REAL_ESTATE ════════════\nfunction GeneralConfig({ businessId, business }: { businessId: string; business: Record<string, unknown> }) {\n  const [saving, setSaving] = useState(false)\n  const [saved,  setSaved]  = useState(false)\n  const [deliveryEnabled, setDeliveryEnabled] = useState((business.delivery_enabled as boolean) ?? true)\n  const [pickupEnabled,   setPickupEnabled]   = useState((business.pickup_enabled as boolean) ?? true)\n\n  async function save() {\n    setSaving(true)\n    await fetch('/api/business/settings', {\n      method: 'PATCH', headers: { 'Content-Type': 'application/json' },\n      body: JSON.stringify({ delivery_enabled: deliveryEnabled, pickup_enabled: pickupEnabled }),\n    })\n    setSaved(true); setTimeout(() => setSaved(false), 2000); setSaving(false)\n  }\n\n  return (\n    <Section title=\"Opciones de contacto\" icon={Store} open>\n      <div className=\"space-y-3\">\n        <Toggle value={deliveryEnabled} onChange={setDeliveryEnabled} label=\"Ofrecer delivery / visita a domicilio\" />\n        <Toggle value={pickupEnabled}   onChange={setPickupEnabled}   label=\"Atención en local / showroom\" />\n        <p className=\"text-xs text-gray-400\">\n          Ajustá los módulos activos cambiando el rubro en la sección de arriba.\n        </p>\n        <SaveBtn onClick={save} saving={saving} saved={saved} />\n      </div>\n    </Section>\n  )\n}\n"

files["app/admin/settings/page.tsx"] = "// app/admin/settings/page.tsx\nimport { createClient } from '@/lib/supabase/server'\nimport { redirect } from 'next/navigation'\nimport SettingsForm from './SettingsForm'\nimport VerticalSettings from './VerticalSettings'\nimport type { Business } from '@/types'\nimport type { VerticalType } from '@/lib/verticals'\nimport Link from 'next/link'\nimport { Palette } from 'lucide-react'\n\nexport const metadata = { title: 'Configuración' }\nexport const dynamic = 'force-dynamic'\n\nexport default async function SettingsPage() {\n  const supabase = await createClient()\n  const { data: { user } } = await supabase.auth.getUser()\n  if (!user) redirect('/auth/login')\n\n  const { data: profile } = await supabase\n    .from('profiles')\n    .select('business_id')\n    .eq('user_id', user.id)\n    .single()\n\n  if (!profile?.business_id) redirect('/admin/onboarding')\n\n  // Cargar negocio fresco\n  const { data: business } = await supabase\n    .from('businesses')\n    .select('*')\n    .eq('id', profile.business_id)\n    .single()\n\n  if (!business) redirect('/admin/onboarding')\n\n  const verticalType = (business.vertical_type ?? 'general') as VerticalType\n\n  // Cargar datos específicos del vertical\n  const [hoursRes, branchesRes, staffRes] = await Promise.all([\n    supabase.from('business_hours').select('*').eq('business_id', profile.business_id).order('day_of_week'),\n    supabase.from('branches').select('id,name,address,phone,is_main').eq('business_id', profile.business_id).eq('active', true),\n    supabase.from('staff').select('id,name,role').eq('business_id', profile.business_id).eq('active', true).order('name'),\n  ])\n\n  const biz = business as Record<string, unknown>\n\n  return (\n    <div className=\"space-y-6 animate-fade-in max-w-2xl\">\n      <div className=\"flex items-center justify-between\">\n        <div>\n          <h1 className=\"text-2xl font-semibold tracking-tight\">Configuración</h1>\n          <p className=\"text-sm text-gray-400 mt-0.5\">Datos y apariencia de tu negocio</p>\n        </div>\n        {/* Acceso rápido al page builder */}\n        <Link href=\"/admin/page-builder\"\n          className=\"flex items-center gap-2 rounded-xl border border-gray-200 bg-white px-4 py-2.5\n                     text-sm font-medium text-gray-700 hover:bg-gray-50 transition-colors shadow-sm\">\n          <Palette size={15} />\n          <span className=\"hidden sm:inline\">Diseñar tienda</span>\n          <span className=\"sm:hidden\">Diseño</span>\n        </Link>\n      </div>\n\n      {/* Configuración general */}\n      <SettingsForm business={business as Business} />\n\n      {/* Configuración específica del vertical */}\n      <VerticalSettings\n        businessId={profile.business_id}\n        verticalType={verticalType}\n        business={biz}\n        hours={hoursRes.data ?? []}\n        branches={branchesRes.data ?? []}\n        staff={staffRes.data ?? []}\n      />\n    </div>\n  )\n}\n"

files["app/admin/page-builder/page.tsx"] = "// app/admin/page-builder/page.tsx\nimport { createClient } from '@/lib/supabase/server'\nimport { redirect } from 'next/navigation'\nimport PageBuilderClient from './PageBuilderClient'\nimport type { Business } from '@/types'\n\nexport const metadata = { title: 'Diseño de tienda' }\nexport const dynamic = 'force-dynamic'\n\nexport default async function PageBuilderPage() {\n  const supabase = await createClient()\n  const { data: { user } } = await supabase.auth.getUser()\n  if (!user) redirect('/auth/login')\n\n  const { data: profile } = await supabase\n    .from('profiles')\n    .select('business_id, business:businesses(*)')\n    .eq('user_id', user.id)\n    .single()\n\n  if (!profile?.business_id) redirect('/admin/onboarding')\n\n  const { data: products } = await supabase\n    .from('products')\n    .select('id, name, price, images, featured, active')\n    .eq('business_id', profile.business_id)\n    .eq('active', true)\n    .order('featured', { ascending: false })\n    .limit(12)\n\n  const { data: categories } = await supabase\n    .from('categories')\n    .select('*')\n    .eq('business_id', profile.business_id)\n    .eq('active', true)\n\n  return (\n    <PageBuilderClient\n      business={profile.business as Business}\n      products={products ?? []}\n      categories={categories ?? []}\n    />\n  )\n}\n"

files["app/admin/page-builder/PageBuilderClient.tsx"] = "// app/admin/page-builder/PageBuilderClient.tsx\n'use client'\nimport { useState, useMemo } from 'react'\nimport { useRouter } from 'next/navigation'\nimport { getVertical } from '@/lib/verticals'\nimport { formatPrice, productImageUrl } from '@/lib/utils'\nimport {\n  Monitor, Smartphone, Check, Loader2, Palette, Type,\n  Layout, Image, ChevronRight, Star, ShoppingBag, Eye,\n  ExternalLink, Layers, RefreshCw,\n} from 'lucide-react'\nimport { cn } from '@/lib/utils'\nimport type { Business } from '@/types'\n\ninterface Product { id: string; name: string; price: number; images: string[]; featured: boolean }\ninterface Category { id: string; name: string; slug: string }\n\ninterface Props {\n  business: Business\n  products: Product[]\n  categories: Category[]\n}\n\ntype DeviceView = 'desktop' | 'mobile'\n\n// Paletas predefinidas por vertical\nconst PALETTES = {\n  food: [\n    { name: 'Fuego',    primary: '#FF5722', secondary: '#ffffff', bg: '#FFF3E0' },\n    { name: 'Noche',    primary: '#1a1a1a', secondary: '#ffffff', bg: '#f5f5f5' },\n    { name: 'Fresco',   primary: '#00BCD4', secondary: '#ffffff', bg: '#E0F7FA' },\n    { name: 'Campo',    primary: '#4CAF50', secondary: '#ffffff', bg: '#F1F8E9' },\n    { name: 'Vino',     primary: '#880E4F', secondary: '#ffffff', bg: '#FCE4EC' },\n  ],\n  barbershop: [\n    { name: 'Clásico',  primary: '#0B1929', secondary: '#C9A84C', bg: '#F7F7F5' },\n    { name: 'Azul',     primary: '#1565FF', secondary: '#ffffff', bg: '#EFF6FF' },\n    { name: 'Negro',    primary: '#111111', secondary: '#ffffff', bg: '#F5F5F5' },\n    { name: 'Vintage',  primary: '#5D4037', secondary: '#FFF8E1', bg: '#EFEBE9' },\n  ],\n  beauty: [\n    { name: 'Rosa',     primary: '#EC4899', secondary: '#ffffff', bg: '#FDF2F8' },\n    { name: 'Lavanda',  primary: '#7C3AED', secondary: '#ffffff', bg: '#F5F3FF' },\n    { name: 'Nude',     primary: '#C2956C', secondary: '#ffffff', bg: '#FDF8F3' },\n    { name: 'Esmeralda',primary: '#059669', secondary: '#ffffff', bg: '#ECFDF5' },\n  ],\n  fashion: [\n    { name: 'Minimalista', primary: '#111111', secondary: '#ffffff', bg: '#FAFAFA' },\n    { name: 'Violeta',  primary: '#7C3AED', secondary: '#ffffff', bg: '#F5F3FF' },\n    { name: 'Dorado',   primary: '#D97706', secondary: '#111111', bg: '#FFFBEB' },\n    { name: 'Rosa nude',primary: '#BE185D', secondary: '#ffffff', bg: '#FDF2F8' },\n  ],\n  general: [\n    { name: 'Azul',     primary: '#1565FF', secondary: '#ffffff', bg: '#EFF6FF' },\n    { name: 'Verde',    primary: '#059669', secondary: '#ffffff', bg: '#ECFDF5' },\n    { name: 'Negro',    primary: '#111111', secondary: '#ffffff', bg: '#F9FAFB' },\n    { name: 'Coral',    primary: '#F43F5E', secondary: '#ffffff', bg: '#FFF1F2' },\n  ],\n}\n\nconst FONTS = [\n  { key: 'inter',    label: 'Inter',    sample: 'Aa', style: { fontFamily: 'Inter, sans-serif' } },\n  { key: 'georgia',  label: 'Georgia',  sample: 'Aa', style: { fontFamily: 'Georgia, serif' } },\n  { key: 'system',   label: 'Sistema',  sample: 'Aa', style: { fontFamily: 'system-ui, sans-serif' } },\n]\n\nconst HERO_STYLES = [\n  { key: 'gradient', label: 'Gradiente', desc: 'Fondo con gradiente de color' },\n  { key: 'image',    label: 'Imagen',    desc: 'Usa tu banner como fondo' },\n  { key: 'minimal',  label: 'Minimalista',desc: 'Texto sobre fondo blanco' },\n  { key: 'dark',     label: 'Oscuro',   desc: 'Fondo negro premium' },\n]\n\nconst LAYOUTS = [\n  { key: 'grid',   label: 'Grilla',   desc: 'Productos en cuadrícula 2×2' },\n  { key: 'list',   label: 'Lista',    desc: 'Fila con imagen y descripción' },\n  { key: 'cards',  label: 'Cards',    desc: 'Tarjetas con imagen grande' },\n]\n\nconst RADIUS_OPTIONS = [\n  { key: 'none', label: 'Angular',  class: 'rounded-none' },\n  { key: 'sm',   label: 'Suave',    class: 'rounded-lg'   },\n  { key: 'lg',   label: 'Redondeado',class: 'rounded-2xl' },\n  { key: 'full', label: 'Pill',     class: 'rounded-full' },\n]\n\nexport default function PageBuilderClient({ business, products, categories }: Props) {\n  const router = useRouter()\n  const vertical = getVertical(business.vertical_type ?? 'general')\n  const paletteKey = (business.vertical_type as keyof typeof PALETTES) in PALETTES\n    ? (business.vertical_type as keyof typeof PALETTES)\n    : 'general'\n  const palettes = PALETTES[paletteKey] ?? PALETTES.general\n\n  // Estado del diseño\n  const [primary,    setPrimary]    = useState(business.primary_color   ?? '#1565FF')\n  const [secondary,  setSecondary]  = useState(business.secondary_color ?? '#ffffff')\n  const [heroStyle,  setHeroStyle]  = useState<string>('gradient')\n  const [heroTitle,  setHeroTitle]  = useState(business.name)\n  const [heroSub,    setHeroSub]    = useState(`${vertical.label} · ${business.address ?? 'Tu ciudad'}`)\n  const [heroCTA,    setHeroCTA]    = useState(\n    vertical.checkoutType === 'booking' ? 'Reservar turno' :\n    vertical.checkoutType === 'lead'    ? 'Consultar' : 'Ver productos'\n  )\n  const [layout,     setLayout]     = useState('list')\n  const [radius,     setRadius]     = useState('lg')\n  const [font,       setFont]       = useState('inter')\n  const [showFeatured, setShowFeatured] = useState(true)\n  const [showCategories, setShowCategories] = useState(true)\n  const [device,     setDevice]     = useState<DeviceView>('mobile')\n  const [activeTab,  setActiveTab]  = useState<'theme'|'hero'|'layout'|'sections'>('theme')\n  const [saving,     setSaving]     = useState(false)\n  const [saved,      setSaved]      = useState(false)\n\n  function applyPalette(p: typeof palettes[0]) {\n    setPrimary(p.primary)\n    setSecondary(p.secondary)\n  }\n\n  async function handleSave() {\n    setSaving(true)\n    const pageConfig = {\n      theme: { primaryColor: primary, secondaryColor: secondary, font, borderRadius: radius },\n      hero:  { style: heroStyle, title: heroTitle, subtitle: heroSub, ctaText: heroCTA },\n      layout: { productLayout: layout, showFeatured, showCategories },\n    }\n    await fetch('/api/business/settings', {\n      method: 'PATCH',\n      headers: { 'Content-Type': 'application/json' },\n      body: JSON.stringify({\n        primary_color:   primary,\n        secondary_color: secondary,\n        page_config:     pageConfig,\n      }),\n    })\n    setSaved(true)\n    setTimeout(() => setSaved(false), 2000)\n    setSaving(false)\n    router.refresh()\n  }\n\n  // Estilo del hero en el preview\n  const heroBackground = useMemo(() => {\n    if (heroStyle === 'image' && business.banner_url)\n      return { backgroundImage: `url(${business.banner_url})`, backgroundSize: 'cover', backgroundPosition: 'center' }\n    if (heroStyle === 'dark')\n      return { background: '#111111' }\n    if (heroStyle === 'minimal')\n      return { background: '#ffffff' }\n    return { background: `linear-gradient(135deg,${primary},${primary}99)` }\n  }, [heroStyle, primary, business.banner_url])\n\n  const heroTextColor = heroStyle === 'minimal' ? primary : (secondary ?? '#ffffff')\n\n  // Radius class\n  const rdClass: Record<string,string> = { none:'rounded-none', sm:'rounded-lg', lg:'rounded-2xl', full:'rounded-full' }\n  const rd = rdClass[radius] ?? 'rounded-2xl'\n\n  return (\n    <div className=\"animate-fade-in\">\n      {/* Header */}\n      <div className=\"flex items-start justify-between gap-4 mb-6\">\n        <div>\n          <h1 className=\"text-xl lg:text-2xl font-bold text-gray-900 tracking-tight\">\n            Diseño de tienda\n          </h1>\n          <p className=\"text-xs text-gray-400 mt-0.5\">\n            Personalizá cómo ven tu negocio los clientes\n          </p>\n        </div>\n        <div className=\"flex items-center gap-2\">\n          {business.slug && (\n            <a href={`/store/${business.slug}`} target=\"_blank\"\n              className=\"flex items-center gap-1.5 rounded-xl border border-gray-200 bg-white px-3 py-2\n                         text-xs font-medium text-gray-600 hover:bg-gray-50 transition-colors\">\n              <ExternalLink size={13} /> Ver tienda\n            </a>\n          )}\n          <button onClick={handleSave} disabled={saving}\n            className=\"flex items-center gap-2 rounded-xl px-4 py-2 text-sm font-semibold text-white disabled:opacity-40\"\n            style={{ background: saved ? '#10B981' : primary }}>\n            {saving ? <Loader2 size={14} className=\"animate-spin\"/> : <Check size={14}/>}\n            {saving ? 'Guardando...' : saved ? 'Guardado ✓' : 'Publicar cambios'}\n          </button>\n        </div>\n      </div>\n\n      <div className=\"grid grid-cols-1 xl:grid-cols-2 gap-6\">\n\n        {/* ── PANEL IZQUIERDO: Controles ── */}\n        <div className=\"space-y-4\">\n\n          {/* Tabs de control */}\n          <div className=\"flex items-center gap-1 bg-gray-100 rounded-xl p-1\">\n            {([\n              { key:'theme',    label:'Colores',  icon: Palette  },\n              { key:'hero',     label:'Hero',     icon: Image    },\n              { key:'layout',   label:'Layout',   icon: Layout   },\n              { key:'sections', label:'Secciones',icon: Layers   },\n            ] as {key:'theme'|'hero'|'layout'|'sections';label:string;icon:React.ElementType}[]).map(({ key, label, icon: Icon }) => (\n              <button key={key} onClick={() => setActiveTab(key)}\n                className={cn('flex items-center gap-1.5 rounded-lg px-3 py-2 text-xs font-medium transition-all flex-1 justify-center',\n                  activeTab === key ? 'bg-white text-gray-900 shadow-sm' : 'text-gray-500 hover:text-gray-700')}>\n                <Icon size={13} />\n                <span className=\"hidden sm:inline\">{label}</span>\n              </button>\n            ))}\n          </div>\n\n          {/* ── COLORES ── */}\n          {activeTab === 'theme' && (\n            <div className=\"bg-white rounded-2xl border border-gray-100 p-5 space-y-5 shadow-sm\">\n              <div>\n                <p className=\"text-sm font-semibold text-gray-800 mb-3\">Paletas para {vertical.label}</p>\n                <div className=\"grid grid-cols-2 sm:grid-cols-3 gap-2\">\n                  {palettes.map(p => (\n                    <button key={p.name} onClick={() => applyPalette(p)}\n                      className={cn('flex items-center gap-2 rounded-xl border p-2.5 transition-all',\n                        primary === p.primary ? 'border-blue-500 bg-blue-50' : 'border-gray-100 hover:border-gray-300')}>\n                      <div className=\"flex shrink-0\">\n                        <div className=\"h-6 w-6 rounded-l-lg\" style={{ background: p.primary }}/>\n                        <div className=\"h-6 w-3 rounded-r-lg border-l border-white/20\" style={{ background: p.secondary }}/>\n                      </div>\n                      <span className=\"text-xs font-medium text-gray-700\">{p.name}</span>\n                    </button>\n                  ))}\n                </div>\n              </div>\n\n              <div className=\"grid grid-cols-2 gap-4\">\n                <div>\n                  <label className=\"field-label text-xs\">Color principal</label>\n                  <div className=\"flex items-center gap-2\">\n                    <input type=\"color\" value={primary} onChange={e => setPrimary(e.target.value)}\n                      className=\"h-9 w-9 rounded-xl border border-gray-200 cursor-pointer p-0.5\"/>\n                    <input type=\"text\" value={primary} onChange={e => setPrimary(e.target.value)}\n                      className=\"input-base font-mono text-xs py-2 flex-1\"/>\n                  </div>\n                </div>\n                <div>\n                  <label className=\"field-label text-xs\">Color secundario</label>\n                  <div className=\"flex items-center gap-2\">\n                    <input type=\"color\" value={secondary} onChange={e => setSecondary(e.target.value)}\n                      className=\"h-9 w-9 rounded-xl border border-gray-200 cursor-pointer p-0.5\"/>\n                    <input type=\"text\" value={secondary} onChange={e => setSecondary(e.target.value)}\n                      className=\"input-base font-mono text-xs py-2 flex-1\"/>\n                  </div>\n                </div>\n              </div>\n\n              <div>\n                <p className=\"text-xs font-semibold text-gray-600 mb-2\">Tipografía</p>\n                <div className=\"grid grid-cols-3 gap-2\">\n                  {FONTS.map(f => (\n                    <button key={f.key} onClick={() => setFont(f.key)}\n                      className={cn('flex flex-col items-center gap-1 rounded-xl border p-3 transition-all',\n                        font === f.key ? 'border-blue-500 bg-blue-50' : 'border-gray-100 hover:border-gray-300')}>\n                      <span className=\"text-xl font-bold text-gray-800\" style={f.style}>{f.sample}</span>\n                      <span className=\"text-[10px] text-gray-500\">{f.label}</span>\n                    </button>\n                  ))}\n                </div>\n              </div>\n\n              <div>\n                <p className=\"text-xs font-semibold text-gray-600 mb-2\">Bordes</p>\n                <div className=\"grid grid-cols-4 gap-2\">\n                  {RADIUS_OPTIONS.map(r => (\n                    <button key={r.key} onClick={() => setRadius(r.key)}\n                      className={cn('flex flex-col items-center gap-1.5 p-2.5 border transition-all',\n                        r.class,\n                        radius === r.key ? 'border-blue-500 bg-blue-50' : 'border-gray-200 hover:border-gray-400')}>\n                      <div className=\"h-4 w-8 border-2 border-current\" style={{\n                        borderRadius: r.key==='none'?'0':r.key==='sm'?'6px':r.key==='lg'?'12px':'999px'\n                      }}/>\n                      <span className=\"text-[10px] text-gray-600\">{r.label}</span>\n                    </button>\n                  ))}\n                </div>\n              </div>\n            </div>\n          )}\n\n          {/* ── HERO ── */}\n          {activeTab === 'hero' && (\n            <div className=\"bg-white rounded-2xl border border-gray-100 p-5 space-y-5 shadow-sm\">\n              <div>\n                <p className=\"text-xs font-semibold text-gray-600 mb-2\">Estilo del hero</p>\n                <div className=\"grid grid-cols-2 gap-2\">\n                  {HERO_STYLES.map(s => (\n                    <button key={s.key} onClick={() => setHeroStyle(s.key)}\n                      className={cn('flex flex-col gap-1 rounded-xl border p-3 text-left transition-all',\n                        heroStyle===s.key?'border-blue-500 bg-blue-50':'border-gray-100 hover:border-gray-300')}>\n                      <p className=\"text-xs font-semibold text-gray-800\">{s.label}</p>\n                      <p className=\"text-[10px] text-gray-500\">{s.desc}</p>\n                    </button>\n                  ))}\n                </div>\n              </div>\n\n              <div className=\"space-y-3\">\n                <div>\n                  <label className=\"field-label text-xs\">Título principal</label>\n                  <input type=\"text\" value={heroTitle} onChange={e => setHeroTitle(e.target.value)}\n                    placeholder=\"Nombre de tu negocio\" className=\"input-base text-sm py-2.5\"/>\n                </div>\n                <div>\n                  <label className=\"field-label text-xs\">Subtítulo</label>\n                  <input type=\"text\" value={heroSub} onChange={e => setHeroSub(e.target.value)}\n                    placeholder=\"Tu slogan o descripción\" className=\"input-base text-sm py-2.5\"/>\n                </div>\n                <div>\n                  <label className=\"field-label text-xs\">Texto del botón</label>\n                  <input type=\"text\" value={heroCTA} onChange={e => setHeroCTA(e.target.value)}\n                    placeholder=\"Ver menú / Reservar / Ver productos\" className=\"input-base text-sm py-2.5\"/>\n                </div>\n              </div>\n            </div>\n          )}\n\n          {/* ── LAYOUT ── */}\n          {activeTab === 'layout' && (\n            <div className=\"bg-white rounded-2xl border border-gray-100 p-5 space-y-5 shadow-sm\">\n              <div>\n                <p className=\"text-xs font-semibold text-gray-600 mb-2\">Layout de productos</p>\n                <div className=\"grid grid-cols-3 gap-2\">\n                  {LAYOUTS.map(l => (\n                    <button key={l.key} onClick={() => setLayout(l.key)}\n                      className={cn('flex flex-col gap-1 rounded-xl border p-3 text-left transition-all',\n                        layout===l.key?'border-blue-500 bg-blue-50':'border-gray-100 hover:border-gray-300')}>\n                      {/* Ícono del layout */}\n                      <div className=\"flex gap-0.5 mb-1\">\n                        {l.key==='grid' && [0,1,2,3].map(i=><div key={i} className=\"h-3 w-3 bg-gray-300 rounded\"/>)}\n                        {l.key==='list' && [0,1,2].map(i=><div key={i} className=\"h-1.5 w-8 bg-gray-300 rounded mb-0.5\" style={{display:'block'}}/>)}\n                        {l.key==='cards' && [0,1].map(i=><div key={i} className=\"h-6 w-5 bg-gray-300 rounded\"/>)}\n                      </div>\n                      <p className=\"text-xs font-semibold text-gray-800\">{l.label}</p>\n                      <p className=\"text-[10px] text-gray-500 leading-tight\">{l.desc}</p>\n                    </button>\n                  ))}\n                </div>\n              </div>\n            </div>\n          )}\n\n          {/* ── SECCIONES ── */}\n          {activeTab === 'sections' && (\n            <div className=\"bg-white rounded-2xl border border-gray-100 p-5 space-y-3 shadow-sm\">\n              <p className=\"text-xs font-semibold text-gray-600\">Secciones visibles</p>\n              {[\n                { key:'showFeatured',    label:'Productos destacados', val:showFeatured,    set:setShowFeatured },\n                { key:'showCategories',  label:'Filtro de categorías', val:showCategories,  set:setShowCategories },\n              ].map(({ key, label, val, set }) => (\n                <label key={key} className=\"flex items-center justify-between py-2 border-b border-gray-50\">\n                  <span className=\"text-sm text-gray-700\">{label}</span>\n                  <button type=\"button\" onClick={() => set(!val)}\n                    className={cn('relative h-5 w-9 rounded-full transition-colors', val?'bg-blue-500':'bg-gray-200')}>\n                    <span className={cn('absolute top-0.5 h-4 w-4 rounded-full bg-white shadow transition-transform',\n                      val?'left-4':'left-0.5')}/>\n                  </button>\n                </label>\n              ))}\n\n              {/* Secciones específicas por vertical */}\n              {vertical.features.hasDelivery && (\n                <div className=\"rounded-xl bg-orange-50 border border-orange-100 px-4 py-3\">\n                  <p className=\"text-xs font-semibold text-orange-800\">🛵 Delivery activado</p>\n                  <p className=\"text-xs text-orange-600 mt-0.5\">\n                    Configurá delivery fee y tiempo en <a href=\"/admin/settings\" className=\"underline\">Configuración</a>\n                  </p>\n                </div>\n              )}\n              {vertical.features.hasBooking && (\n                <div className=\"rounded-xl bg-blue-50 border border-blue-100 px-4 py-3\">\n                  <p className=\"text-xs font-semibold text-blue-800\">📅 Reservas online activas</p>\n                  <p className=\"text-xs text-blue-600 mt-0.5\">\n                    Los clientes pueden reservar desde tu tienda pública\n                  </p>\n                </div>\n              )}\n            </div>\n          )}\n        </div>\n\n        {/* ── PANEL DERECHO: Preview ── */}\n        <div className=\"space-y-3\">\n          {/* Device toggle */}\n          <div className=\"flex items-center justify-between\">\n            <p className=\"text-sm font-semibold text-gray-700\">Vista previa</p>\n            <div className=\"flex items-center gap-1 bg-gray-100 rounded-xl p-1\">\n              {([\n                { key:'desktop', icon: Monitor    },\n                { key:'mobile',  icon: Smartphone },\n              ] as {key:DeviceView;icon:React.ElementType}[]).map(({ key, icon: Icon }) => (\n                <button key={key} onClick={() => setDevice(key)}\n                  className={cn('flex h-8 w-8 items-center justify-center rounded-lg transition-all',\n                    device===key?'bg-white shadow-sm text-gray-900':'text-gray-400 hover:text-gray-700')}>\n                  <Icon size={15}/>\n                </button>\n              ))}\n            </div>\n          </div>\n\n          {/* Preview frame */}\n          <div className={cn(\n            'mx-auto overflow-hidden border border-gray-200 shadow-xl transition-all duration-300',\n            device === 'mobile' ? 'w-[320px] rounded-[32px]' : 'w-full rounded-2xl'\n          )}>\n            <div className=\"overflow-y-auto\" style={{ maxHeight: device==='mobile'?'580px':'520px', background:'#f9f9f8' }}>\n\n              {/* ── HERO PREVIEW ── */}\n              <div className=\"relative\" style={{ ...heroBackground, minHeight: device==='mobile'?'180px':'200px' }}>\n                {heroStyle==='image' && business.banner_url && (\n                  <div className=\"absolute inset-0 bg-black/40\"/>\n                )}\n                <div className=\"relative flex flex-col items-center justify-center h-full py-10 px-5 text-center\">\n                  {business.logo_url && (\n                    <img src={business.logo_url} alt=\"\"\n                      className={cn('h-12 w-12 object-cover mb-3', rd)}/>\n                  )}\n                  <h1 className=\"font-bold text-lg leading-tight\" style={{ color: heroTextColor }}>\n                    {heroTitle}\n                  </h1>\n                  <p className=\"text-xs mt-1 opacity-80\" style={{ color: heroTextColor }}>\n                    {heroSub}\n                  </p>\n                  <button className={cn('mt-4 px-5 py-2 text-xs font-bold transition-all', rd)}\n                    style={{ background: secondary, color: primary }}>\n                    {heroCTA}\n                  </button>\n                </div>\n              </div>\n\n              {/* ── CATEGORIES PREVIEW ── */}\n              {showCategories && categories.length > 0 && (\n                <div className=\"flex gap-2 px-3 py-3 overflow-x-auto scrollbar-hide\">\n                  {['Todo',...categories.map(c=>c.name)].map(cat => (\n                    <span key={cat}\n                      className={cn('shrink-0 px-3 py-1 text-[10px] font-semibold', rd,\n                        cat==='Todo'?'text-white':'bg-white text-gray-600 border border-gray-200')}\n                      style={cat==='Todo'?{background:primary}:{}}>\n                      {cat}\n                    </span>\n                  ))}\n                </div>\n              )}\n\n              {/* ── FEATURED ── */}\n              {showFeatured && products.some(p=>p.featured) && (\n                <div className=\"px-3 pb-2\">\n                  <p className=\"text-[10px] font-bold text-gray-500 mb-2 uppercase tracking-wide\">⭐ Destacados</p>\n                  <div className=\"flex gap-2 overflow-x-auto scrollbar-hide\">\n                    {products.filter(p=>p.featured).slice(0,3).map(p=>(\n                      <div key={p.id} className={cn('shrink-0 w-28 bg-white border border-gray-100 overflow-hidden', rd)}>\n                        <div className=\"h-16 bg-gray-100 overflow-hidden\">\n                          <img src={productImageUrl(p.images)} alt=\"\" className=\"h-full w-full object-cover\"/>\n                        </div>\n                        <div className=\"p-1.5\">\n                          <p className=\"text-[9px] font-bold text-gray-900 truncate\">{p.name}</p>\n                          <p className=\"text-[9px] font-bold mt-0.5\" style={{color:primary}}>\n                            {formatPrice(p.price,'UYU')}\n                          </p>\n                        </div>\n                      </div>\n                    ))}\n                  </div>\n                </div>\n              )}\n\n              {/* ── PRODUCTOS PREVIEW ── */}\n              <div className=\"px-3 pb-4\">\n                <p className=\"text-[10px] font-bold text-gray-500 mb-2 uppercase tracking-wide\">Productos</p>\n                {layout === 'grid' && (\n                  <div className=\"grid grid-cols-2 gap-2\">\n                    {products.slice(0,4).map(p=>(\n                      <div key={p.id} className={cn('bg-white border border-gray-100 overflow-hidden', rd)}>\n                        <div className=\"h-16 bg-gray-100\">\n                          <img src={productImageUrl(p.images)} alt=\"\" className=\"h-full w-full object-cover\"/>\n                        </div>\n                        <div className=\"p-1.5\">\n                          <p className=\"text-[9px] font-bold text-gray-900 truncate\">{p.name}</p>\n                          <div className=\"flex items-center justify-between mt-1\">\n                            <p className=\"text-[9px] font-bold\" style={{color:primary}}>{formatPrice(p.price,'UYU')}</p>\n                            <div className=\"h-4 w-4 rounded-full flex items-center justify-center text-white text-[8px]\"\n                              style={{background:primary}}>+</div>\n                          </div>\n                        </div>\n                      </div>\n                    ))}\n                  </div>\n                )}\n                {layout === 'list' && (\n                  <div className=\"space-y-2\">\n                    {products.slice(0,3).map(p=>(\n                      <div key={p.id} className={cn('flex items-center gap-2 bg-white border border-gray-100 p-2', rd)}>\n                        <div className=\"h-10 w-10 bg-gray-100 shrink-0 overflow-hidden rounded-lg\">\n                          <img src={productImageUrl(p.images)} alt=\"\" className=\"h-full w-full object-cover\"/>\n                        </div>\n                        <div className=\"flex-1 min-w-0\">\n                          <p className=\"text-[9px] font-bold text-gray-900 truncate\">{p.name}</p>\n                          <p className=\"text-[9px] font-bold\" style={{color:primary}}>{formatPrice(p.price,'UYU')}</p>\n                        </div>\n                        <div className=\"h-6 w-6 rounded-lg flex items-center justify-center text-white text-xs shrink-0\"\n                          style={{background:primary}}>+</div>\n                      </div>\n                    ))}\n                  </div>\n                )}\n                {layout === 'cards' && (\n                  <div className=\"grid grid-cols-1 gap-3\">\n                    {products.slice(0,2).map(p=>(\n                      <div key={p.id} className={cn('bg-white border border-gray-100 overflow-hidden', rd)}>\n                        <div className=\"h-24 bg-gray-100\">\n                          <img src={productImageUrl(p.images)} alt=\"\" className=\"h-full w-full object-cover\"/>\n                        </div>\n                        <div className=\"p-2\">\n                          <p className=\"text-[10px] font-bold text-gray-900\">{p.name}</p>\n                          <div className=\"flex items-center justify-between mt-1.5\">\n                            <p className=\"text-[10px] font-bold\" style={{color:primary}}>{formatPrice(p.price,'UYU')}</p>\n                            <button className={cn('px-2 py-1 text-[9px] font-bold text-white', rd)}\n                              style={{background:primary}}>Agregar</button>\n                          </div>\n                        </div>\n                      </div>\n                    ))}\n                  </div>\n                )}\n              </div>\n            </div>\n          </div>\n\n          {/* Nota */}\n          <p className=\"text-xs text-center text-gray-400\">\n            Vista previa aproximada · Guardá para ver los cambios en la tienda real\n          </p>\n        </div>\n      </div>\n    </div>\n  )\n}\n"

files["app/api/business/settings/route.ts"] = "// app/api/business/settings/route.ts\nimport { createClient } from '@/lib/supabase/server'\nimport { createServiceClient } from '@/lib/supabase/server'\nimport { NextResponse } from 'next/server'\n\nconst ALLOWED = [\n  'name','whatsapp','address','currency','primary_color','secondary_color',\n  'logo_url','banner_url','instagram','tiktok','website','vertical_type',\n  'delivery_enabled','pickup_enabled','delivery_fee','min_order','estimated_time',\n  'page_config','enabled_modules','dashboard_config',\n]\n\nexport async function PATCH(req: Request) {\n  try {\n    const supabase = await createClient()\n    const { data: { user }, error: authError } = await supabase.auth.getUser()\n    if (authError || !user)\n      return NextResponse.json({ error: 'No autorizado' }, { status: 401 })\n\n    const { data: profile } = await supabase\n      .from('profiles').select('business_id').eq('user_id', user.id).single()\n\n    if (!profile?.business_id)\n      return NextResponse.json({ error: 'Sin negocio' }, { status: 403 })\n\n    const body = await req.json()\n    const payload: Record<string, unknown> = {}\n\n    for (const key of ALLOWED) {\n      if (!(key in body)) continue\n      // Limpiezas específicas\n      if (key === 'whatsapp')        payload[key] = (body[key] ?? '').replace(/[^\\d]/g, '') || null\n      else if (key === 'name')       payload[key] = (body[key] ?? '').trim() || null\n      else if (['address','logo_url','banner_url','website'].includes(key))\n                                     payload[key] = (body[key] ?? '').trim() || null\n      else if (['instagram','tiktok'].includes(key))\n                                     payload[key] = (body[key] ?? '').trim().replace(/^@/,'') || null\n      else                           payload[key] = body[key]\n    }\n\n    if (!payload.name && 'name' in payload)\n      return NextResponse.json({ error: 'El nombre es obligatorio' }, { status: 400 })\n\n    const service = createServiceClient()\n    const { data, error } = await service\n      .from('businesses').update(payload).eq('id', profile.business_id)\n      .select('id,name,whatsapp,slug,vertical_type,primary_color').single()\n\n    if (error) {\n      console.error('[settings PATCH]', error)\n      return NextResponse.json({ error: error.message }, { status: 500 })\n    }\n\n    return NextResponse.json({ ok: true, business: data })\n  } catch (err) {\n    console.error('[settings PATCH] unexpected:', err)\n    return NextResponse.json({ error: 'Error interno' }, { status: 500 })\n  }\n}\n"

for (const [p,c] of Object.entries(files)) {
  const d = path.dirname(p)
  if (!fs.existsSync(d)) fs.mkdirSync(d,{recursive:true})
  fs.writeFileSync(p,c,'utf8')
  console.log('  OK ' + p)
}
